          "--bento-rows": layout.rows,
          ...style,
        } as React.CSSProperties
      }
    >
      {variant === "interlock" && (
        <svg
          className="v-bento__paint"
          viewBox={`0 0 ${layout.columns} ${layout.rows}`}
